-- Migration: monthly AI advice (generated by a cron job, served from a cache).
-- Run once in the Supabase SQL editor (after 20261018000000_ai_advice_usage.sql). Re-runnable.
--
-- Privacy model:
--   * ai_advice_settings: each user's explicit opt-in plus the ANONYMOUS summary they chose to share
--     (monthly totals, goal progress; descriptions only if include_labels). The user owns and can erase it.
--   * ai_advice_cache: the advice texts generated for that user. The user can read and delete them;
--     only the cron function (service role) can create them.
--   * The cron job reads only these two tables, never transactions / rental / savings records,
--     so the "admins cannot access user content" guarantee is unchanged.

begin;

-- On-demand generation is gone, so the per-request quota table is no longer needed
drop table if exists public.ai_advice_usage;

create table if not exists public.ai_advice_settings (
  user_id uuid primary key default auth.uid() references auth.users(id) on delete cascade,
  enabled boolean not null default false,
  include_labels boolean not null default false,
  summary jsonb check (summary is null or pg_column_size(summary) < 20000),
  summary_at timestamptz,
  updated_at timestamptz not null default now()
);

create table if not exists public.ai_advice_cache (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  period text not null check (period ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  advice text not null check (length(advice) <= 4000),
  model text,
  created_at timestamptz not null default now(),
  constraint ai_advice_cache_user_period_key unique (user_id, period)
);

create or replace function public.ai_advice_settings_touch()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists ai_advice_settings_touch on public.ai_advice_settings;
create trigger ai_advice_settings_touch
  before update on public.ai_advice_settings
  for each row execute function public.ai_advice_settings_touch();

alter table public.ai_advice_settings enable row level security;
alter table public.ai_advice_cache enable row level security;

drop policy if exists "own rows" on public.ai_advice_settings;
create policy "own rows" on public.ai_advice_settings for all to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

drop policy if exists "read own advice" on public.ai_advice_cache;
drop policy if exists "delete own advice" on public.ai_advice_cache;
create policy "read own advice" on public.ai_advice_cache for select to authenticated
  using ((select auth.uid()) = user_id);
create policy "delete own advice" on public.ai_advice_cache for delete to authenticated
  using ((select auth.uid()) = user_id);

-- Users cannot write or edit advice (it is produced only by the cron function with the service role)
revoke insert, update on public.ai_advice_cache from anon, authenticated;
revoke all on public.ai_advice_settings from anon;
revoke all on public.ai_advice_cache from anon;

commit;
